using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using LWS.TruckSports.Editor;
namespace LWS.TruckTerrierRacing.Editor {
public static class TerrierCourseArtAuthoring {
 const string Folder="TruckTerrierRacing",RampPath="Assets/TruckTerrierRacing/Prefabs/Timber launch ramp.prefab",HurdlePath="Assets/TruckTerrierRacing/Prefabs/Construction jump hurdle.prefab";
 public static void Install(TerrierMatch m){System.IO.Directory.CreateDirectory("Assets/TruckTerrierRacing/Prefabs");AssetDatabase.Refresh();var ramp=Ramp();var hurdle=Hurdle();for(int i=0;i<m.course.ramps.Length;i++){var old=m.course.ramps[i];var g=(GameObject)PrefabUtility.InstantiatePrefab(ramp);g.name="Timber jump ramp "+i;g.transform.position=new Vector3((i%3-1)*11,0,44+i/3*55);UnityEngine.Object.DestroyImmediate(old.gameObject);m.course.ramps[i]=g.transform;}for(int i=0;i<m.course.hurdles.Length;i++){var old=m.course.hurdles[i];var g=(GameObject)PrefabUtility.InstantiatePrefab(hurdle);g.name="Construction jump hurdle "+i;g.transform.SetPositionAndRotation(old.position,Quaternion.identity);g.transform.localScale=old.localScale;UnityEngine.Object.DestroyImmediate(old.gameObject);m.course.hurdles[i]=g.transform;}EditorUtility.SetDirty(m.course);}
 static GameObject Ramp(){var root=new GameObject("Timber launch ramp");var contact=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>("Assets/TruckTerrierRacing/Materials/Track contact.asset");var metal=SportsEventAuthoring.Mat(Folder,"Ramp steel",new Color(.10f,.14f,.17f),.62f);var edge=SportsEventAuthoring.Mat(Folder,"Ramp edge paint",new Color(1,.68f,.1f),.35f);
 var mesh=new Mesh{name="Welded wedge ramp frame"};mesh.vertices=new[]{new Vector3(-4,0,-3),new Vector3(4,0,-3),new Vector3(-4,.04f,-3),new Vector3(4,.04f,-3),new Vector3(-4,0,3),new Vector3(4,0,3),new Vector3(-4,1.04f,3),new Vector3(4,1.04f,3)};mesh.triangles=new[]{0,2,3,0,3,1,2,6,7,2,7,3,4,5,7,4,7,6,0,4,6,0,6,2,1,3,7,1,7,5,0,1,5,0,5,4};mesh.RecalculateNormals();mesh.RecalculateBounds();string path="Assets/TruckTerrierRacing/Materials/Timber ramp collision.asset";var asset=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(asset==null){AssetDatabase.CreateAsset(mesh,path);asset=mesh;}else{EditorUtility.CopySerialized(mesh,asset);UnityEngine.Object.DestroyImmediate(mesh);}var collider=root.AddComponent<MeshCollider>();collider.sharedMesh=asset;collider.sharedMaterial=contact;root.AddComponent<TerrierJumpObstacle>();
 // Deck reuses the installed textured timber mesh. Each plank follows the physical launch slope.
 var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ConstructionPropsBundle/URP/Prefabs/SM_Planks01 Variant.prefab");if(source==null)throw new Exception("Installed construction timber missing");var filter=source.GetComponentInChildren<MeshFilter>();var material=filter.GetComponent<MeshRenderer>().sharedMaterials;var b=filter.sharedMesh.bounds;for(int i=0;i<8;i++){var plank=new GameObject("Textured timber deck plank "+i);plank.transform.SetParent(root.transform,false);plank.transform.localRotation=Quaternion.Euler(-Mathf.Atan(1f/6)*Mathf.Rad2Deg,0,0);plank.transform.localScale=new Vector3(.98f/b.size.x,.06f/b.size.y,Mathf.Sqrt(37)/b.size.z);plank.transform.localPosition=new Vector3(i-3.5f,.57f,0)-plank.transform.localRotation*Vector3.Scale(plank.transform.localScale,b.center);plank.AddComponent<MeshFilter>().sharedMesh=filter.sharedMesh;plank.AddComponent<MeshRenderer>().sharedMaterials=material;}
 for(int side=-1;side<=1;side+=2){var beam=new GameObject("Triangular welded side frame");beam.transform.SetParent(root.transform,false);beam.AddComponent<MeshFilter>().sharedMesh=asset;beam.AddComponent<MeshRenderer>().sharedMaterial=metal;beam.transform.localScale=new Vector3(.018f,1,1);beam.transform.localPosition=new Vector3(side*3.92f,0,0);var stripe=SportsEventAuthoring.Box("Painted launch edge",new Vector3(side*3.9f,.58f,0),new Vector3(.1f,.07f,6.08f),edge,null,root.transform);stripe.transform.localRotation=Quaternion.Euler(-Mathf.Atan(1f/6)*Mathf.Rad2Deg,0,0);for(int k=0;k<3;k++){var brace=SportsEventAuthoring.Box("Steel cross brace",new Vector3(0,.12f+k*.22f,-2+k*2),new Vector3(7.8f,.09f,.1f),metal,null,root.transform);}}
 var prefab=PrefabUtility.SaveAsPrefabAsset(root,RampPath);UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static GameObject Hurdle(){var root=new GameObject("Construction jump hurdle");var shape=root.AddComponent<BoxCollider>();shape.sharedMaterial=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>("Assets/TruckTerrierRacing/Materials/Track contact.asset");root.AddComponent<TerrierJumpObstacle>();var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RoadPropsPack/URP/Prefabs/RoadBlock02_URP.prefab");if(source==null)throw new Exception("Installed road barrier model missing");var sourceFilter=source.GetComponentInChildren<MeshFilter>();var b=sourceFilter.sharedMesh.bounds;for(int i=0;i<20;i++){var g=new GameObject("Striped jump barrier "+i);g.transform.SetParent(root.transform,false);g.transform.localScale=new Vector3(.05f/b.size.x,1/b.size.y,1/b.size.z);g.transform.localPosition=new Vector3(-.475f+i*.05f,0,0)-Vector3.Scale(g.transform.localScale,b.center);g.AddComponent<MeshFilter>().sharedMesh=sourceFilter.sharedMesh;g.AddComponent<MeshRenderer>().sharedMaterials=sourceFilter.GetComponent<MeshRenderer>().sharedMaterials;}var prefab=PrefabUtility.SaveAsPrefabAsset(root,HurdlePath);UnityEngine.Object.DestroyImmediate(root);return prefab;}
}
}
